// src/api.js

import mockData from "./mock-data";

/**
 *
 * @param {*} events:
 * The following function should be in the "api.js" file.
 * This function takes an events array, then uses map to create a new array with only locations.
 * It will also remove all duplicates by creating another new array using the spread operator and spreading a Set.
 * The Set will remove all duplicates from the array.
 */

export const extractLocations = (events) => {
  const extractedLocations = events.map((event) => event.location);
  const locations = [...new Set(extractedLocations)];
  return locations;
};

const checkToken = async (accessToken) => {
  const response = await fetch(
    `https://www.googleapis.com/oauth2/v1/tokeninfo?access_token=${accessToken}`
  );
  const result = await response.json();
  return result;
};

const removeQuery = () => {
  let newurl;
  if (window.history.pushState && window.location.pathname) {
    newurl =
      window.location.protocol +
      "//" +
      window.location.host +
      window.location.pathname;
    window.history.pushState("", "", newurl);
  } else {
    newurl = window.location.protocol + "//" + window.location.host;
    window.history.pushState("", "", newurl);
  }
};

const getToken = async (code) => {
  const encodeCode = encodeURIComponent(code);
  const response = await fetch(
    "https://q0w5lkoaz3.execute-api.us-west-1.amazonaws.com/dev/api/token" +
      "/" +
      encodeCode
  );
  const { access_token } = await response.json();
  access_token && localStorage.setItem("access_token", access_token);

  return access_token;
};

/**
 *
 * This function will fetch the list of all events
 */

export const getEvents = async () => {
  if (window.location.href.startsWith("http://localhost")) {
    return mockData;
  }

  if (!navigator.onLine) {
    const events = localStorage.getItem("lastEvents");
    return events ? JSON.parse(events) : [];
  }

  const token = await getAccessToken();

  if (token) {
    removeQuery();
    // Corrected endpoint from "/spi/get-events" to "/api/get-events"
    const url =
      "https://q0w5lkoaz3.execute-api.us-west-1.amazonaws.com/dev/api/get-events" +
      "/" +
      token;
    const response = await fetch(url);
    const result = await response.json();

    if (result && result.events) {
      localStorage.setItem("lastEvents", JSON.stringify(result.events));
      return result.events;
    } else return [];
  }
};

/**
 *
 * This function is to get the Access Token for the API
 *
 */

export const getAccessToken = async () => {
  const accessToken = localStorage.getItem("access_token");

  const tokenCheck = accessToken && (await checkToken(accessToken));

  if (!accessToken || tokenCheck.error) {
    await localStorage.removeItem("access_token");
    const searchParams = new URLSearchParams(window.location.search);
    const code = searchParams.get("code");

    if (!code) {
      try {
        const response = await fetch(
          "https://q0w5lkoaz3.execute-api.us-west-1.amazonaws.com/dev/api/get-auth-url"
        );
        const result = await response.json();
        const { authUrl } = result;

        if (authUrl) {
          window.location.href = authUrl;
        } else {
          console.error("No authUrl returned from server:", result);
        }
      } catch (error) {
        console.error("Error fetching get-auth-url:", error);
      }
      return;
    }
    return code && getToken(code);
  }
  return accessToken;
};
